<div class="page-head"><div><h1><?= e(__('Announcements')) ?></h1><p><?= e(__('Shown on everyone\'s dashboard between the publish and expiry dates.')) ?></p></div></div>
<div class="split"><div><?php foreach ($rows as $a): ?><div class="card"><div class="card-head"><h2 class="h3"><?= e($a['title']) ?></h2><?php if (can('announcements.manage')): ?><form method="post" action="<?= e(url('/announcements/' . $a['id'] . '/delete')) ?>" data-confirm="<?= e(__('Delete?')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-danger"><?= e(__('Delete')) ?></button></form><?php endif; ?></div><p><?= nl2br(e($a['body'])) ?></p><p class="small muted"><?= e(fmt_date($a['publish_on'])) ?><?= $a['expires_on'] ? ' – ' . e(fmt_date($a['expires_on'])) : '' ?></p></div><?php endforeach; ?>
<?php if (!$rows): ?><div class="card"><p class="empty"><?= e(__('No announcements.')) ?></p></div><?php endif; ?></div>
<?php if (can('announcements.manage')): ?><div class="card"><h2 class="h3"><?= e(__('New announcement')) ?></h2><form method="post" action="<?= e(url('/announcements')) ?>" class="form"><?= csrf_field() ?><label><?= e(__('Title')) ?><input name="title" required></label><label><?= e(__('Message')) ?><textarea name="body" required></textarea></label><div class="grid-2"><label><?= e(__('Publish from')) ?><input type="date" name="publish_on" value="<?= e(date('Y-m-d')) ?>"></label><label><?= e(__('Expires')) ?><input type="date" name="expires_on"></label></div><button class="btn btn-primary"><?= e(__('Publish')) ?></button></form></div><?php endif; ?>
</div>
